content.text:
{
  "pipeline_id": "alignment-wes",
  "name": "Short-Read Alignment (WES/WGS)",
  "description": "Alignment-only pipeline for whole exome or whole genome sequencing short reads. Covers FastQC QC, Trimmomatic adapter trimming, BWA-MEM alignment, SAMtools coordinate sorting and indexing, and Picard duplicate marking. Produces an analysis-ready BAM file suitable for variant calling, coverage analysis, or any downstream BAM-based tools.",
  "estimated_duration": "2-6 hours",
  "inputs": [
    {
      "name": "inputFastqR1",
      "type": "file",
      "required": true,
      "description": "Read 1 FASTQ file (.fastq.gz)"
    },
    {
      "name": "inputFastqR2",
      "type": "file",
      "required": true,
      "description": "Read 2 FASTQ file (.fastq.gz)"
    },
    {
      "name": "referenceGenome",
      "type": "string",
      "required": false,
      "default": "references/GRCh38/hg38.fa",
      "description": "Reference genome FASTA (must be indexed)"
    },
    {
      "name": "sampleName",
      "type": "string",
      "required": false,
      "default": "sample",
      "description": "Sample identifier"
    }
  ],
  "steps": [
    {
      "step": 1,
      "tool": "fastqc",
      "description": "Quality check raw reads before alignment"
    },
    {
      "step": 2,
      "tool": "trimmomatic",
      "description": "Remove adapters and trim low-quality bases",
      "after": [
        "step1_fastqc"
      ]
    },
    {
      "step": 3,
      "tool": "bwa",
      "description": "BWA-MEM alignment of paired-end reads to reference genome",
      "after": [
        "step2_trim"
      ]
    },
    {
      "step": 4,
      "tool": "samtools",
      "description": "Coordinate-sort BAM for downstream tools",
      "after": [
        "step3_align"
      ]
    },
    {
      "step": 5,
      "tool": "picard",
      "description": "Mark PCR and optical duplicates",
      "after": [
        "step4_sort"
      ]
    },
    {
      "step": 6,
      "tool": "samtools",
      "description": "Index the analysis-ready BAM",
      "after": [
        "step5_markdup"
      ]
    }
  ]
}

